from itertools import product

def count_valid(k):
    count = 0
    digits = [0, 1, 2, 8]
    for p in product(digits, repeat=k):
        if p[0] == 0:
            continue
        if sum(p) % 3 == 0:
            count += 1
    return count

for k in range(1, 5):
    print(f"k={k}, count={count_valid(k)}")
